# Also check with broader food quality terms
alaska_food_quality = []
for row in dataset:
    if row['company_id'] == 'AlaskaAir':
        dialog_lower = row['dialog'].lower()
        has_food = any(w in dialog_lower for w in ['food', 'meal', 'snack', 'sandwich', 'chicken', 'catering'])
        has_negative = any(w in dialog_lower for w in ['bad', 'terrible', 'awful', 'horrible', 'gross', 'disgusting', 'worst', 'poor', 'suck', 'yuck', 'nasty', 'inedible', 'cold', 'stale'])
        if has_food and has_negative:
            alaska_food_quality.append(row)

print(f"\n\nAlaskaAir dialogs with food + negative terms: {len(alaska_food_quality)}")
for r in alaska_food_quality:
